'use client';

import Layout from '@/components/layout/layout';
import AuthGuard from '@/components/auth/auth-guard';
import { Cog6ToothIcon, BellIcon, ShieldCheckIcon, MoonIcon, SunIcon } from '@heroicons/react/24/outline';

export default function SettingsPage() {
  return (
    <AuthGuard>
      <Layout>
        <div className="space-y-6">
          {/* Page Header */}
          <div>
            <h1 className="text-2xl font-bold text-primary">Settings</h1>
            <p className="mt-1 text-sm text-text-secondary">
              Configure your admin dashboard preferences
            </p>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            {/* Profile Settings */}
            <div className="card p-6">
              <h3 className="text-lg font-medium text-primary mb-4">Profile Settings</h3>
              <div className="space-y-4">
                <div>
                  <label className="block text-sm font-medium text-primary mb-2">Display Name</label>
                  <input
                    type="text"
                    defaultValue="Admin User"
                    className="input-field w-full"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-primary mb-2">Email</label>
                  <input
                    type="email"
                    defaultValue="admin@pos.com"
                    className="input-field w-full"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-primary mb-2">Timezone</label>
                  <select className="input-field w-full">
                    <option>UTC-08:00</option>
                    <option>UTC-05:00</option>
                    <option>UTC-06:00</option>
                  </select>
                </div>
              </div>
            </div>

            {/* Notification Settings */}
            <div className="card p-6">
              <h3 className="text-lg font-medium text-primary mb-4">Notifications</h3>
              <div className="space-y-4">
                <div className="flex items-center justify-between">
                  <div>
                    <label className="text-sm font-medium text-primary">Email Notifications</label>
                    <p className="text-xs text-text-secondary">Receive daily summaries</p>
                  </div>
                  <button className="relative inline-flex h-6 w-11 items-center rounded-full bg-primary transition-colors">
                    <span className="sr-only">Email Notifications</span>
                    <span className="translate-x-0 inline-block h-4 w-4 rounded-full bg-white shadow-sm ring-offset-2 transition-transform duration-200 ease-in-out"></span>
                  </button>
                </div>
                <div className="flex items-center justify-between">
                  <div>
                    <label className="text-sm font-medium text-primary">Low Stock Alerts</label>
                    <p className="text-xs text-text-secondary">Alert when products run low</p>
                  </div>
                  <button className="relative inline-flex h-6 w-11 items-center rounded-full bg-success transition-colors">
                    <span className="sr-only">Low Stock Alerts</span>
                    <span className="translate-x-0 inline-block h-4 w-4 rounded-full bg-white shadow-sm ring-offset-2 transition-transform duration-200 ease-in-out"></span>
                  </button>
                </div>
                <div className="flex items-center justify-between">
                  <div>
                    <label className="text-sm font-medium text-primary">Transfer Notifications</label>
                    <p className="text-xs text-text-secondary">Alert on stock transfers</p>
                  </div>
                  <button className="relative inline-flex h-6 w-11 items-center rounded-full bg-info transition-colors">
                    <span className="sr-only">Transfer Notifications</span>
                    <span className="translate-x-0 inline-block h-4 w-4 rounded-full bg-white shadow-sm ring-offset-2 transition-transform duration-200 ease-in-out"></span>
                  </button>
                </div>
              </div>
            </div>

            {/* Appearance Settings */}
            <div className="card p-6">
              <h3 className="text-lg font-medium text-primary mb-4">Appearance</h3>
              <div className="space-y-4">
                <div className="flex items-center justify-between">
                  <div>
                    <label className="text-sm font-medium text-primary">Theme</label>
                    <p className="text-xs text-text-secondary">Choose color scheme</p>
                  </div>
                  <div className="flex space-x-2">
                    <button className="flex items-center space-x-2 p-2 rounded-lg border-2 border-primary bg-primary text-white">
                      <SunIcon className="h-4 w-4" />
                      <span>Light</span>
                    </button>
                    <button className="flex items-center space-x-2 p-2 rounded-lg border border-divider bg-surface text-primary">
                      <MoonIcon className="h-4 w-4" />
                      <span>Dark</span>
                    </button>
                  </div>
                </div>
                <div className="flex items-center justify-between">
                  <div>
                    <label className="text-sm font-medium text-primary">Compact Mode</label>
                    <p className="text-xs text-text-secondary">Reduce UI density</p>
                  </div>
                  <button className="relative inline-flex h-6 w-11 items-center rounded-full bg-surface border border-divider transition-colors">
                    <span className="sr-only">Compact Mode</span>
                    <span className="translate-x-0 inline-block h-4 w-4 rounded-full bg-white shadow-sm ring-offset-2 transition-transform duration-200 ease-in-out"></span>
                  </button>
                </div>
              </div>
            </div>

            {/* Security Settings */}
            <div className="card p-6">
              <h3 className="text-lg font-medium text-primary mb-4">Security</h3>
              <div className="space-y-4">
                <div className="flex items-center justify-between">
                  <div>
                    <label className="text-sm font-medium text-primary">Two-Factor Auth</label>
                    <p className="text-xs text-text-secondary">Extra security layer</p>
                  </div>
                  <button className="relative inline-flex h-6 w-11 items-center rounded-full bg-warning transition-colors">
                    <span className="sr-only">Two-Factor Auth</span>
                    <span className="translate-x-0 inline-block h-4 w-4 rounded-full bg-white shadow-sm ring-offset-2 transition-transform duration-200 ease-in-out"></span>
                  </button>
                </div>
                <div className="flex items-center justify-between">
                  <div>
                    <label className="text-sm font-medium text-primary">Session Timeout</label>
                    <p className="text-xs text-text-secondary">Auto-logout duration</p>
                  </div>
                  <select className="input-field w-32">
                    <option>15 minutes</option>
                    <option>30 minutes</option>
                    <option>1 hour</option>
                    <option>4 hours</option>
                  </select>
                </div>
              </div>
            </div>

            {/* System Settings */}
            <div className="card p-6">
              <h3 className="text-lg font-medium text-primary mb-4">System</h3>
              <div className="space-y-4">
                <div className="flex items-center justify-between">
                  <div>
                    <label className="text-sm font-medium text-primary">Data Export</label>
                    <p className="text-xs text-text-secondary">Download all data</p>
                  </div>
                  <button className="btn-secondary">
                    <ShieldCheckIcon className="h-4 w-4 mr-2" />
                    Export Data
                  </button>
                </div>
                <div className="flex items-center justify-between">
                  <div>
                    <label className="text-sm font-medium text-primary">Clear Cache</label>
                    <p className="text-xs text-text-secondary">Reset performance</p>
                  </div>
                  <button className="btn-secondary">
                    <Cog6ToothIcon className="h-4 w-4 mr-2" />
                    Clear Cache
                  </button>
                </div>
                <div className="flex items-center justify-between">
                  <div>
                    <label className="text-sm font-medium text-primary">System Status</label>
                    <p className="text-xs text-text-secondary">View health metrics</p>
                  </div>
                  <button className="btn-secondary">
                    <BellIcon className="h-4 w-4 mr-2" />
                    View Status
                  </button>
                </div>
              </div>
            </div>
          </div>
        </div>
      </Layout>
    </AuthGuard>
  );
}
